operation.query:
SET @ReturnValue = 0;
INSERT INTO [NonGBVAttachment] ([NonGBVDetailID] ,[Filename] ,[FileAttached] ,[ContentType] ,[CreationUserID] ,[LastModificationTimestamp] ,[LastModificationUserID] ,[Deleted]) VALUES (@NonGBVDetailID ,@Filename ,@FileAttached ,@ContentType ,@CreationUserID ,@LastModificationTimestamp ,@LastModificationUserID ,0);
SET @ReturnValue = SCOPE_IDENTITY();

IF(NOT EXISTS (SELECT NonGBVAttachmentID FROM NonGBVAttachment WHERE DELETED = 0 AND NonGBVAttachmentID = @NonGBVAttachmentID)) SET @ReturnValue = 0;
ELSE
BEGIN
UPDATE [NonGBVAttachment] SET [Filename] = @Filename ,[FileAttached] = @FileAttached ,[ContentType] = @ContentType ,[LastModificationTimestamp] = @LastModificationTimestamp ,[LastModificationUserID] = @LastModificationUserID ,[Deleted] = 0 WHERE [Deleted] = 0 and NonGBVAttachmentID = @NonGBVAttachmentID
SET @ReturnValue = 1;
END

IF(NOT EXISTS (SELECT NonGBVAttachmentID FROM NonGBVAttachment WHERE DELETED = 0 AND NonGBVAttachmentID = @NonGBVAttachmentID)) SET @ReturnValue = 0;
ELSE
BEGIN
UPDATE [NonGBVAttachment] SET [LastModificationTimestamp] = GETDATE() ,[LastModificationUserID] = @UserID ,[Deleted] = 1 WHERE NonGBVAttachmentID = @NonGBVAttachmentID
SET @ReturnValue = 1;
END
